"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisHowItWorksContent } from "./components/how-it-works/content";
import View3 from "./components/how-it-works/variants/04-walkthrough";
const variants = {"walkthrough":View3};
export type { ArtemisHowItWorksContent, ArtemisHowItWorksLink, ArtemisHowItWorksStep } from "./components/how-it-works/content";
export interface ArtemisHowItWorksProps { className?: string; variant?: "walkthrough"; /** The words on the how-it-works section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisHowItWorksContent>; }
export function ArtemisHowItWorks({ className, variant = "walkthrough", content }: ArtemisHowItWorksProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisHowItWorksLink {
  label: string;
  href: string;
}

/** One step of the process. Layouts number the steps in order and draw their own scene for each one. */
export interface ArtemisHowItWorksStep {
  /** A short label over the title, such as "Collect". All layouts. Keep labels unique, since story-stack and card-deck tell steps apart by it. */
  label: string;
  /** The step's title. All layouts. */
  title: string;
  /** A sentence or two under the title. All layouts; card-deck shows two lines of it. */
  description: string;
  /** The step's icon. centered-cards, process-grid, walkthrough and card-deck, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis how-it-works section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisHowItWorksContent {
  /** The small pill over the headline. All layouts. */
  badge: string;
  /** The heading. All layouts; process-grid, story-stack, walkthrough and card-deck break it into two lines at the middle word. */
  headline: string;
  /** A line or two beside or under the headline. All layouts. */
  subhead: string;
  /** The button after the steps or beside the subhead. centered-cards, process-grid, story-stack and walkthrough. */
  cta?: ArtemisHowItWorksLink;
  /** The steps, in order. All layouts; three look best, and card-deck's own list has four. */
  steps: ArtemisHowItWorksStep[];
}

"use client";
// @zeus-internal
import { ArrowRight } from "lucide-react";
import { AnimatePresence, motion, type Transition, useInView, useReducedMotion } from "motion/react";
import { type ComponentType, useEffect, useRef, useState } from "react";
import { ArtemisButton, ArtemisButtonLink } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import type { ArtemisHowItWorksContent } from "../content";
import { AUTOPLAY_MS, defaultHeadline, defaultSteps, ICONS } from "./04-walkthrough/data";
import { WalkthroughScene } from "./04-walkthrough/scenes";
import { WalkthroughShader } from "./04-walkthrough/shader";
const DEFAULT = {
    badge: "A guided workflow",
    headline: defaultHeadline,
    subhead: "Follow the complete path without hiding the context between steps.",
    cta: { label: "Try the workflow", href: "#" },
    steps: defaultSteps,
} satisfies ArtemisHowItWorksContent;
/** The walkthrough draws three scenes; later steps take them in turn. */
const SCENE_COUNT = 3;
const INSTANT: Transition = { duration: 0 };
function wordTransition(index: number): Transition {
    const delay = index * 0.06;
    return {
        opacity: { duration: 0.7, delay, ease: ARTEMIS_EASE_OUT },
        filter: { duration: 0.9, delay, ease: ARTEMIS_EASE_OUT },
        y: { type: "spring", stiffness: 140, damping: 26, mass: 1.2, delay },
    };
}
function Headline({ text }: {
    text: string;
}) {
    const ref = useRef<HTMLHeadingElement>(null);
    const inView = useInView(ref, { once: true, amount: 0.4 });
    const reduce = useReducedMotion();
    const words = text.split(" ");
    const lines = [words.slice(0, Math.floor(words.length / 2)), words.slice(Math.floor(words.length / 2))];
    let index = 0;
    return (<h2 ref={ref} className="art:block art:mt-7 art:max-w-4xl art:text-balance art:tracking-[-0.055em] art:text-4xl art:font-medium">
      {lines.map((line) => (<span key={line.join(" ")} className="art:block">
          {line.map((word, i) => {
                const wordIndex = index++;
                return (<motion.span key={word} className="art:inline-block art:will-change-transform" initial={{ opacity: 0, filter: "blur(10px)", y: "24%" }} animate={inView || reduce ? { opacity: 1, filter: "blur(0px)", y: "0%" } : undefined} transition={reduce ? INSTANT : wordTransition(wordIndex)}>
                {word}
                {i < line.length - 1 ? <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span> : null}
              </motion.span>);
            })}
        </span>))}
    </h2>);
}
export default function HowItWorksWalkthrough({ content }: { content?: Partial<ArtemisHowItWorksContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const sectionRef = useRef<HTMLElement>(null);
    const inView = useInView(sectionRef, { margin: "120px" });
    const reduce = useReducedMotion();
    const [active, setActive] = useState(0);
    useEffect(() => {
        if (!inView)
            return;
        const id = window.setTimeout(() => setActive((current) => (current + 1) % copy.steps.length), AUTOPLAY_MS);
        return () => window.clearTimeout(id);
    }, [active, inView]);
    return (<section ref={sectionRef} className="art:w-full art:overflow-hidden art:bg-background art:px-4 art:py-20 art:text-foreground art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-24 art:@min-[1024px]/artemis:px-8 art:@min-[1024px]/artemis:py-28">
      <div className="art:mx-auto art:w-full art:max-w-7xl">
        <div className="art:grid art:items-end art:gap-8 art:@min-[1024px]/artemis:grid-cols-[1.2fr_0.8fr] art:@min-[1024px]/artemis:gap-16">
          <div>
            <motion.span className="art:inline-flex art:rounded-full art:border art:border-border/70 art:bg-background art:px-3 art:py-1.5 art:font-medium art:text-muted-foreground art:text-xs" initial={{ opacity: 0, filter: "blur(5px)", transform: "translate3d(0,8px,0)" }} whileInView={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0)" }} viewport={{ once: true, margin: "-50px" }} transition={reduce ? INSTANT : { duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
              {copy.badge}
            </motion.span>
            <Headline text={copy.headline}/>
          </div>
          <motion.div className="art:max-w-xl art:@min-[1024px]/artemis:justify-self-end" initial={{ opacity: 0, transform: "translate3d(0,10px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={{ once: true, margin: "-50px" }} transition={reduce ? INSTANT : { duration: 0.5, delay: 0.3, ease: ARTEMIS_EASE_OUT }}>
            <p className="art:text-pretty art:text-muted-foreground art:text-sm art:leading-6 art:@min-[640px]/artemis:text-base art:@min-[640px]/artemis:leading-7">
              {copy.subhead}
            </p>
            <ArtemisButtonLink href={copy.cta.href} variant="secondary" className="art:mt-6 art:w-fit art:h-9">
              {copy.cta.label}
              <ArrowRight className="art:size-4"/>
            </ArtemisButtonLink>
          </motion.div>
        </div>

        <motion.div className="art:mt-14 art:grid art:gap-3 art:rounded-3xl art:border art:border-border/70 art:bg-background art:p-3 art:@min-[640px]/artemis:mt-16 art:@min-[1024px]/artemis:grid-cols-[1.45fr_0.85fr]" initial={{ opacity: 0, transform: "translate3d(0,18px,0)" }} whileInView={{ opacity: 1, transform: "translate3d(0,0,0)" }} viewport={{ once: true, margin: "-70px" }} transition={reduce ? INSTANT : { duration: 0.65, ease: ARTEMIS_EASE_OUT }}>
          <div className="art:relative art:min-h-[27rem] art:overflow-hidden art:rounded-3xl art:border art:border-border/70 art:@min-[640px]/artemis:min-h-[32rem]">
            <WalkthroughShader />
            <AnimatePresence initial={false} mode="wait">
              <motion.div key={active} className="art:absolute art:inset-0" initial={{ opacity: 0, filter: "blur(7px)", transform: "scale(0.985)" }} animate={{ opacity: 1, filter: "blur(0px)", transform: "scale(1)" }} exit={{ opacity: 0, filter: "blur(6px)", transform: "scale(0.985)" }} transition={{ duration: 0.42, ease: ARTEMIS_EASE_OUT }}>
                <div className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:p-6 art:@min-[640px]/artemis:p-10">
                  <WalkthroughScene step={active % SCENE_COUNT}/>
                </div>
              </motion.div>
            </AnimatePresence>
          </div>

          <div className="art:grid art:gap-2 art:@min-[1024px]/artemis:grid-rows-3">
            {copy.steps.map((step, i) => {
            const selected = i === active;
            const number = String(i + 1).padStart(2, "0");
            const Icon: ComponentType<{ className?: string; strokeWidth?: number }> = step.icon ?? ICONS[i % ICONS.length];
            return (<ArtemisButton key={number} variant="ghost" size="none" aria-pressed={selected} onClick={() => setActive(i)} className={artemisCx("art:h-auto art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:flex art:min-h-[10rem] art:w-full art:flex-col art:border art:p-5 art:text-left art:outline-none art:transition-colors art:duration-300 art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-card art:@min-[640px]/artemis:p-6", selected ? "art:border-border art:bg-background" : "art:border-transparent art:bg-transparent")}>
                  <span className="art:flex art:w-full art:items-center art:justify-between">
                    <span className="art:font-medium art:text-muted-foreground art:text-xs art:tabular-nums">{number}</span>
                    <span className={artemisCx("art:grid art:size-9 art:place-items-center art:rounded-full art:transition-colors art:duration-300", selected ? "art:bg-foreground art:text-background" : "art:bg-muted art:text-muted-foreground")}>
                      <Icon className="art:size-4" strokeWidth={1.7}/>
                    </span>
                  </span>
                  <span className="art:mt-4 art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">{step.label}</span>
                  <span className="art:mt-2 art:font-medium art:text-xl art:tracking-[-0.03em]">{step.title}</span>
                  <span className="art:mt-2 art:max-w-sm art:text-pretty art:text-muted-foreground art:text-xs art:leading-5">{step.description}</span>
                </ArtemisButton>);
        })}
          </div>
        </motion.div>
      </div>
    </section>);
}

// @zeus-internal
import { LayoutDashboard, type LucideIcon, MessageSquareText, Rocket, UsersRound } from "lucide-react";
import type { ArtemisHowItWorksStep } from "../../content";
/** The steps the walkthrough shows when it is given none. */
export const defaultSteps: ArtemisHowItWorksStep[] = [
    {
        label: "Listen",
        title: "Gather the real request",
        description: "Capture the language, examples, and context behind what people are asking for.",
    },
    {
        label: "Align",
        title: "Shape one shared direction",
        description: "Turn the raw signal into a brief with an outcome, an owner, and a clear next move.",
    },
    {
        label: "Release",
        title: "Publish the finished work",
        description: "Review the details against the brief, move it live, and share the result with the team.",
    },
];
/** The icon for each slot, in turn; a step without an icon keeps its slot's. */
export const ICONS = [MessageSquareText, LayoutDashboard, Rocket];
export interface ListenMessage {
    author: string;
    text: string;
    icon: LucideIcon;
    right: boolean;
}
export const LISTEN_MESSAGES: readonly ListenMessage[] = [
    { author: "Alex", text: "Can we keep the review context beside the work?", icon: MessageSquareText, right: false },
    { author: "Morgan", text: "The team needs one place to see what changed.", icon: MessageSquareText, right: true },
    { author: "Customer call", text: "Make the next step obvious without another meeting.", icon: UsersRound, right: false },
];
export const BRIEF_ROWS: readonly {
    label: string;
    value: string;
}[] = [
    { label: "Outcome", value: "A clearer review flow" },
    { label: "Owner", value: "Product team" },
    { label: "Next move", value: "Prototype the handoff" },
];
/** The headline the walkthrough shows when it is given none; it breaks into two lines at the middle word. */
export const defaultHeadline = "See the work take shape, one decision at a time.";
export const AUTOPLAY_MS = 5600;
export const SHADER_COLORS = ["#f6dfc7", "#e8b99b", "#d5c4aa", "#f0cfae"];

"use client";
// @zeus-internal
import { Check, ClipboardPenLine, Sparkles } from "lucide-react";
import { motion } from "motion/react";
import { artemisCx } from "../../../../lib/utils";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { BRIEF_ROWS, LISTEN_MESSAGES } from "./data";
const GLASS = "art:border art:border-border/70 art:bg-background/48 art:backdrop-blur-xl art:supports-[backdrop-filter]:bg-background/35";
function ListenScene() {
    return (<div className="art:w-full art:max-w-lg art:space-y-3">
      {LISTEN_MESSAGES.map((message, i) => {
            const Icon = message.icon;
            return (<motion.div key={message.author} className={artemisCx("art:max-w-[88%] art:rounded-2xl art:border art:border-border/70 art:bg-background/48 art:p-4 art:backdrop-blur-xl art:supports-[backdrop-filter]:bg-background/35", message.right && "art:ml-auto")} initial={{ opacity: 0, transform: `translate3d(${message.right ? 18 : -18}px,0,0)` }} animate={{ opacity: 1, transform: "translate3d(0,0,0)" }} transition={{ duration: 0.5, delay: i * 0.08, ease: ARTEMIS_EASE_OUT }}>
            <div className="art:flex art:items-center art:gap-3">
              <span className="art:grid art:size-8 art:place-items-center art:rounded-full art:bg-muted">
                <Icon className="art:size-3.5" strokeWidth={1.7}/>
              </span>
              <span className="art:font-medium art:text-xs">{message.author}</span>
            </div>
            <p className="art:mt-3 art:text-pretty art:text-sm art:leading-6">{message.text}</p>
          </motion.div>);
        })}
    </div>);
}
function AlignScene() {
    return (<div className={artemisCx("art:w-full art:max-w-lg art:rounded-3xl art:p-5 art:@min-[640px]/artemis:p-7", GLASS)}>
      <div className="art:flex art:items-center art:justify-between">
        <div>
          <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">Shared brief</p>
          <p className="art:mt-2 art:font-semibold art:text-2xl art:tracking-[-0.04em]">Review workspace</p>
        </div>
        <span className="art:grid art:size-11 art:place-items-center art:rounded-full art:bg-muted">
          <ClipboardPenLine className="art:size-5" strokeWidth={1.7}/>
        </span>
      </div>
      <div className="art:mt-6 art:grid art:gap-2">
        {BRIEF_ROWS.map((row, i) => (<motion.div key={row.label} className="art:grid art:gap-1 art:rounded-xl art:border art:border-border/65 art:bg-background/40 art:px-4 art:py-3 art:@min-[640px]/artemis:grid-cols-[6rem_1fr] art:@min-[640px]/artemis:items-center" initial={{ opacity: 0, transform: "translate3d(0,10px,0)" }} animate={{ opacity: 1, transform: "translate3d(0,0,0)" }} transition={{ duration: 0.42, delay: 0.12 + i * 0.07, ease: ARTEMIS_EASE_OUT }}>
            <span className="art:text-muted-foreground art:text-xs">{row.label}</span>
            <span className="art:font-medium art:text-sm">{row.value}</span>
          </motion.div>))}
      </div>
    </div>);
}
function ReleaseScene() {
    return (<motion.div className="art:w-full art:max-w-md art:rounded-3xl art:border art:border-border/70 art:bg-background/48 art:p-7 art:text-center art:backdrop-blur-xl art:supports-[backdrop-filter]:bg-background/35 art:@min-[640px]/artemis:p-9" initial={{ opacity: 0, filter: "blur(8px)", transform: "translate3d(0,16px,0) scale(0.98)" }} animate={{ opacity: 1, filter: "blur(0px)", transform: "translate3d(0,0,0) scale(1)" }} transition={{ duration: 0.6, ease: ARTEMIS_EASE_OUT }}>
      <span className="art:mx-auto art:grid art:size-14 art:place-items-center art:rounded-full art:bg-foreground art:text-background">
        <Check className="art:size-6"/>
      </span>
      <p className="art:mt-5 art:font-semibold art:text-2xl art:tracking-[-0.04em]">Ready for everyone</p>
      <p className="art:mx-auto art:mt-3 art:max-w-xs art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
        The work is live with the decisions, owner, and outcome still attached.
      </p>
      <div className="art:mt-6 art:flex art:items-center art:justify-center art:gap-2">
        <span className="art:rounded-full art:border art:border-border/70 art:bg-background/35 art:px-3 art:py-1.5 art:font-medium art:text-xs">Published</span>
        <span className="art:rounded-full art:border art:border-border/70 art:bg-background/35 art:px-3 art:py-1.5 art:font-medium art:text-xs">Shared</span>
        <Sparkles className="art:size-4 art:text-muted-foreground" strokeWidth={1.7}/>
      </div>
    </motion.div>);
}
export function WalkthroughScene({ step }: {
    step: number;
}) {
    if (step === 1)
        return <AlignScene />;
    if (step === 2)
        return <ReleaseScene />;
    return <ListenScene />;
}

"use client";
// @zeus-internal
import { MeshGradient } from "@paper-design/shaders-react";
import { SHADER_COLORS } from "./data";
export function WalkthroughShader() {
    return (<div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0">
      <MeshGradient className="art:h-full art:w-full" colors={SHADER_COLORS} distortion={0.48} swirl={0.26} speed={0.12}/>
      <div className="art:absolute art:inset-0 art:bg-background/12 art:dark:bg-background/52"/>
    </div>);
}
